steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "{
    teams(name: \"Web\") {
      nodes {
        id
        name
        workflowStates(filter: {type: {eq: \"started\"}}) {
          nodes {
            id
            name
          }
        }
        issueLabels {
          nodes {
            id
            name
            team {
              id
            }
          }
        }
      }
    }
    users(filter: {name: {contains: \"Maya Chen\"}}) {
      nodes {
        id
        name
      }
    }
  }
}'
